class CheXbert(nn.Module):
    def __init__(self, bert_path, chexbert_path, device, p=0.1):
        super(CheXbert, self).__init__()
        self.device = device
        self.tokenizer = BertTokenizer.from_pretrained(bert_path)
        config = BertConfig().from_pretrained(bert_path)
        with torch.no_grad():
            self.bert = BertModel(config)
            self.dropout = nn.Dropout(p)
            hidden_size = self.bert.pooler.dense.in_features
            self.linear_heads = nn.ModuleList([nn.Linear(hidden_size, 4, bias=True) for _ in range(13)])
            self.linear_heads.append(nn.Linear(hidden_size, 2, bias=True))
            state_dict = torch.load(chexbert_path, map_location=device)['model_state_dict']
            new_state_dict = OrderedDict()
            for key, value in state_dict.items():
                if 'bert' in key: new_key = key.replace('module.bert.', 'bert.')
                elif 'linear_heads' in key: new_key = key.replace('module.linear_heads.', 'linear_heads.')
                new_state_dict[new_key] = value
            self.load_state_dict(new_state_dict)
        self.eval()
    def forward(self, reports):
        for i in range(len(reports)):
            reports[i] = reports[i].strip(); reports[i] = reports[i].replace("
", " "); reports[i] = reports[i].replace("\s+", " "); reports[i] = reports[i].replace("\s+(?=[\.,])", ""); reports[i] = reports[i].strip()
        with torch.no_grad():
            tokenized = self.tokenizer(reports, padding='longest', max_length=512, return_tensors="pt", truncation=True); tokenized = {k: v.to(self.device) for k, v in tokenized.items()}
            last_hidden_state = self.bert(**tokenized)[0]; cls = last_hidden_state[:, 0, :]; cls = self.dropout(cls)
            predictions = [];
            for i in range(14): predictions.append(self.linear_heads[i](cls).argmax(dim=1))
        return torch.stack(predictions, dim=1)

