        if symmetric: W = (W + W.permute(1,0))/2; W = 1 - W
    if mode == 'agreement': logits = (logits + logits.permute(1,0,2))/2; W = logits.argmax(-1) == 2
    if mode == 'agreement_w': W = torch.softmax(logits/temp, dim=-1)[:, :, 2];
        if symmetric: W = (W + W.permute(1,0))/2
