    def get_acc(self, acc_name='generations|rougeL|acc', test=False):
        pref, name, suffix = acc_name.split("|"); assert pref == 'generations' and name in {'rougeL', 'gpt', 'chexbert'}, f'Unknown type {acc_name}'
        if name == 'rougeL':
            scores = []
            score_df = pd.DataFrame(scores, index=self.ids)
        elif name == 'gpt':
            score_df = pd.DataFrame(np.zeros((len(self.ids), len(self.gpt_eval))), index=self.ids)
            for ith, vals in self.gpt_eval.items():
                for j, val in enumerate(vals): _id = val['id']; val = int(val['response']) if isinstance(val['response'], str) and val['response'].isdigit() else np.NaN
