            if name == 'rougeL': indiv_acc = (indiv_acc > 0.3).astype(float)
            elif name == 'gpt': indiv_acc = (indiv_acc > 0.7).astype(float)
            elif name == 'chexbert': indiv_acc = (indiv_acc >= 12/14).astype(float)
        if test: indiv_acc = indiv_acc.loc[list(self.test_ids)]; return indiv_acc.mean(1), indiv_acc
