    def _tune_params(self, num_gens=20, metric:str=None, temperature=[0.1, 0.25, 0.5, 1, 3, 5, 7], eigv_threshold = [0.4, 0.5, 0.6, 0.7, 0.8, 0.9], curve='auarc', overall=False, use_conf=True,):
        import itertools; best_params = defaultdict(dict); all_kwargs = {'temperature': temperature, 'eigv_threshold': eigv_threshold}
        for uq_name, tunable_params in self.tunable_hyperparams.items():
            uqs = {};
            if uq_name not in self.uq_measures: continue
            kwargs = {k: all_kwargs[k] for k in tunable_params}
            for _vals in itertools.product(*[kwargs[_] for _ in tunable_params]):
                _kwargs = dict(zip(tunable_params, _vals)); uqs[str(_kwargs)] = self.get_uq(uq_name, num_gens=num_gens, **_kwargs)
            if metric is not None:
                summ_obj = Summarizer(uqs, self.get_acc(metric))
                best_params[uq_name] = eval(summ_obj.find_best_uq_name(metric=curve, overall=overall, use_conf=use_conf))
        return dict(best_params)
    def summ(self, uq_names:list, uq_list:list, acc_name:str, num_gens=20, uq_kwargs_ref:dict=None, uq_kwargs:dict=None, overall=False, use_conf=True, test=False):
        if uq_kwargs is None:
            uq_kwargs = {}
