                assert self.key[2] == 'test'
                self2 = self.__class__(self.path, self.batch_num, self.batch_size, self.key[1], 'val', self.key[3], self.key[4], self.key[5])
                self2.tunable_hyperparams = {k:v for k, v in self.tunable_hyperparams.items() if k in uq_names}
                tuned_hyperparams = self2._tune_params(num_gens=num_gens, metric=acc_name, overall=overall, use_conf=use_conf, curve='auarc')
                uq_kwargs.update(tuned_hyperparams)
            else: uq_kwargs.update(self._get_default_params())
        if isinstance(uq_names, str): uq_names = [uq_names]
        if not test:
            summ_obj = Summarizer({_: self.get_uq(_, num_gens, **uq_kwargs.get(_,{})) for _ in uq_names}, self.get_acc(acc_name), lengths = self.get_length(num_gens)[1])
        else:
            summ_obj = Summarizer({_: self.get_uq_all(_, uq_list, acc_name, num_gens, uq_kwargs_ref, uq_kwargs) for _ in uq_names}, self.get_acc(acc_name,True), lengths = self.get_length(num_gens)[1])
        return summ_obj
    def _get_default_params(self, ):
        hyparams = {}
        for uq_name in self.uq_measures:
